DO $ext$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'vector') OR EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'vector') THEN
    CREATE EXTENSION IF NOT EXISTS "vector";
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'knowledge_base' AND column_name = 'embedding') THEN
      ALTER TABLE "public"."knowledge_base" ADD COLUMN "embedding" vector(1536);
      COMMENT ON COLUMN "public"."knowledge_base"."embedding" IS 'platform-migration:declared-shape-convergence';
    END IF;
  ELSE
    RAISE NOTICE 'platform shape convergence: extension vector is not available on this server, so public.knowledge_base.embedding is not created.';
  END IF;
END
$ext$;
--> statement-breakpoint
