DO $tag$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT n.nspname AS schema_name, c.relname AS table_name, a.attname AS column_name, c.oid AS rel_oid, a.attnum,
           CASE
             WHEN p.column_name IS NULL THEN 'platform-migration:declared-shape-convergence'
             WHEN p.has_default = false AND a.atthasdef THEN 'platform-migration:declared-shape-convergence:default'
             WHEN p.nullable = false AND NOT a.attnotnull THEN 'platform-migration:declared-shape-convergence:relax'
           END AS tag
      FROM pg_attribute a
      JOIN pg_class c ON c.oid = a.attrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
      LEFT JOIN platform_convergence_pre p ON p.schema_name = n.nspname AND p.table_name = c.relname AND p.column_name = a.attname
     WHERE (n.nspname, c.relname) IN (VALUES ('public', 'ab_test_assignments'), ('public', 'ab_test_events'), ('public', 'ab_test_variants'), ('public', 'ab_tests'), ('public', 'access_justification_requests'), ('public', 'accessibility_audits'), ('public', 'accessibility_issues'), ('public', 'account_balance_reconciliation'), ('public', 'account_mappings'), ('public', 'address_change_history'), ('public', 'address_validation_cache'), ('public', 'ai_budgets'), ('public', 'alert_recipients'), ('public', 'api_access_tokens'), ('public', 'api_integrations'), ('public', 'arbitrator_profiles'), ('public', 'arms_length_verification'), ('audit_security', 'security_events'), ('public', 'automation_rules'), ('public', 'autopay_settings'), ('public', 'award_history'), ('public', 'award_templates'), ('public', 'band_council_consent'), ('public', 'band_councils'), ('public', 'bank_of_canada_rates'), ('public', 'bank_reconciliation'), ('public', 'bargaining_team_members'), ('public', 'bargaining_units'), ('public', 'benchmark_categories'), ('public', 'benefit_comparisons'), ('public', 'blind_trust_registry'), ('public', 'break_glass_activations'), ('public', 'break_glass_system'), ('public', 'budget_pool'), ('public', 'budget_reservations'), ('public', 'cba_clauses'), ('public', 'cba_contacts'), ('public', 'cba_footnotes'), ('public', 'cba_version_history'), ('public', 'certification_alerts'), ('public', 'certification_audit_log'), ('public', 'certification_compliance_reports'), ('public', 'certification_types'), ('public', 'chart_of_accounts'), ('public', 'claim_deadlines'), ('public', 'claims'), ('public', 'clc_bargaining_trends'), ('public', 'clc_chart_of_accounts'), ('public', 'clc_oauth_tokens'), ('public', 'clc_per_capita_benchmarks'), ('public', 'clc_sync_log'), ('public', 'clc_union_density'), ('public', 'clc_webhook_log'), ('public', 'collective_agreements'), ('public', 'committees'), ('public', 'communication_analytics'), ('public', 'communication_preferences'), ('publ