n_only_data_tags'), ('public', 'user_consents'), ('public', 'user_engagement_scores'), ('public', 'user_sessions'), ('public', 'user_uuid_mapping'), ('public', 'voting_audit_log'), ('public', 'voting_notifications'), ('public', 'voting_sessions'), ('public', 'wage_progressions'), ('public', 'wcag_success_criteria'), ('public', 'webhook_events'), ('public', 'webhook_subscriptions'), ('public', 'weekly_threshold_tracking'), ('public', 'whiplash_prevention_audit'), ('public', 'whiplash_violations'), ('public', 'worksites')) AND a.attnum > 0 AND NOT a.attisdropped
  LOOP
    IF r.tag IS NOT NULL AND col_description(r.rel_oid, r.attnum) IS NULL THEN
      EXECUTE format('COMMENT ON COLUMN %I.%I.%I IS %L', r.schema_name, r.table_name, r.column_name, r.tag);
    END IF;
  END LOOP;
END
